class ProtocolRegistry:
    _handlers = {
        (3, 0): 'HandlerVersion3_0',
        (3, 1): 'HandlerVersion3_1',
        (3, 2): 'HandlerVersion3_2',
        (3, 3): 'HandlerVersion3_3',
        (3, 4): 'HandlerVersion3_4',
        (3, 5): 'HandlerVersion3_5',
    }

    @classmethod
    def protocol_handlers(cls, protocol_version=None):
        if protocol_version is not None and not isinstance(protocol_version, tuple):
            raise TypeError("Protocol version must be passed in a tuple")

        if protocol_version is None:
            return dict(cls._handlers)

        return {protocol_version: cls._handlers[protocol_version]} if protocol_version in cls._handlers else {}

# Example usage
