from neo4j import Transaction

def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        @wraps(func)
        def wrapper(tx: Transaction, *args, **kwargs):
            return func(tx, *args, **kwargs)
        wrapper._is_unit_of_work = True
        wrapper._metadata = metadata
        wrapper._timeout = timeout
        return wrapper
    return decorator

