from shapely.geometry import Point
import types

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    def __init__(self, *args, **kwargs):
        Point.__init__(self, *args)
        for field in fields:
            setattr(self, field, kwargs.get(field, None))
        self._srid = srid_map.get(name, None)

    def __repr__(self):
        return f"{name}({Point.__repr__(self)}, {', '.join(f'{field}={getattr(self, field, None)}' for field in fields)}, srid={self._srid})"

    attributes = {
        '__init__': __init__,
        '__repr__': __repr__,
    }

    for field in fields:
        attributes[field] = None

    return types.new_class(name, (Point,), {}, lambda ns: ns.update(attributes))

# Example usage
if __name__ == "__main__":
    CustomPoint = point_type('CustomPoint', ['elevation', 'temperature'], {'CustomPoint': 4326})
    point = CustomPoint(1, 2, elevation=100, temperature=25)
    print(point)
    print(point.elevation)
    print(point.temperature)
    print(point._srid)

import warnings
import functools

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

