import threading

def cached(cache, key=hash, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            if lock is not None:
                with lock:
                    return cached_call(*args, **kwargs)
            else:
                return cached_call(*args, **kwargs)

        def cached_call(*args, **kwargs):
            k = key(*args, **kwargs)
            if k in cache:
                return cache[k]
            result = func(*args, **kwargs)
            cache[k] = result
            return result

        return wrapper

    return decorator

