import time

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        cache = Cache(maxsize, ttl, timer, typed)
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            return cache.get_or_create(*args, **kwargs)
        return wrapper
    return decorator

class Cache:
    def __init__(self, maxsize, ttl, timer, typed):
        self.cache = functools.lru_cache(maxsize=maxsize, typed=typed)(self._timed_cache)
        self.ttl = ttl
        self.timer = timer

    def get_or_create(self, *args, **kwargs):
        return self.cache(*args, **kwargs)

    def _timed_cache(self, *args, **kwargs):
        result, timestamp = self.cache.cache_get(*args, **kwargs)
        if result is not None and self.timer() - timestamp < self.ttl:
            return result
        result = self._func(*args, **kwargs)
        self.cache.cache_set(*args, **kwargs, value=(result, self.timer()))
        return result

    def _func(self, *args, **kwargs):
        raise NotImplementedError("Cache._func should be set to the function to be cached")

    class _LRUCacheWrapper:
        def __init__(self, func, maxsize, typed):
            self.func = func
            self.cache = {}
            self.maxsize = maxsize
            self.typed = typed
            self.order = []

        def cache_get(self, *args, **kwargs):
            key = self._make_key(args, kwargs)
            if key in self.cache:
                self.order.remove(key)
                self.order.append(key)
                return self.cache[key]
            return None, None

        def cache_set(self, *args, **kwargs, value):
            key = self._make_key(args, kwargs)
            if key in self.cache:
                self.order.remove(key)
            self.cache[key] = value
            self.order.append(key)
            if self.maxsize and len(self.cache) > self.maxsize:
                oldest_key = self.order.pop

from functools import lru_cache

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    def decorator(func):
        cache = lru_cache(maxsize=maxsize, typed=typed)
        def wrapper(*args, **kwargs):
            return cache(func)(*args, **kwargs)
        return wrapper
    return decorator

