from functools import lru_cache, wraps
from collections import Counter

def lfu_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        hits = Counter()
        misses = Counter()
        full = False

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = args if typed else args + tuple(kwargs.items())
            if key in cache:
                hits[key] += 1
                return cache[key]
            else:
                misses[key] += 1
                result = func(*args, **kwargs)
                cache[key] = result
                if len(cache) > maxsize:
                    full = True
                    lfu_key = min(cache, key=hits.get)
                    del cache[lfu_key]
                    del hits[lfu_key]
                return result

        def cache_info():
            return (hits.total(), misses.total(), maxsize, len(cache))

        def cache_clear():
            cache.clear()
            hits.clear()
            misses.clear()

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        return wrapper

    return decorator

# Example usage:
@lfu_cache(maxsize=2)
def example_function(x):
    return x * x

# Test the cache
print(example_function(1))  # miss, cache {1: 1}
print(example_function(2))  # miss, cache {1: 1, 2: 4}
print(example_function(1))  # hit, cache {1: 1, 2: 4}
print(example_function(3))  # miss, cache {1: 1, 3: 9}, evicts 2
print(example_function(2))  # miss, cache {3: 9, 2: 4}, evicts 1

