import traceback

class ExceptionFormatter:
    @classmethod
    def extostr(cls, e, max_level=30, max_path_level=5):
        stack = traceback.extract_tb(e.__traceback__, limit=max_level)
        formatted_stack = []
        for frame in stack:
            filename = '/'.join(frame.filename.split('/')[-max_path_level:])
            formatted_stack.append(f"  File \"{filename}\", line {frame.lineno}, in {frame.name}")
            if frame.line:
                formatted_stack.append(f"    {frame.line.strip()}")
        formatted_exception = f"{type(e).__name__}: {str(e)}\n" + "\n".join(formatted_stack)
        return formatted_exception

# Example usage
