from collections import defaultdict

def _legacy_mergeOrderings(orderings):
    def build_graph(orderings):
        graph = defaultdict(list)
        for ordering in orderings:
            for pos in range(len(ordering) - 1):
                graph[ordering[pos]].append(ordering[pos + 1])
        return graph

    def find_sinks(graph):
        sinks = set(graph.keys())
        for v in graph:
            for w in graph[v]:
                sinks.discard(w)
        return sinks

    def topological_sort(graph, sinks):
        ordered = []
        while sinks:
            n = sinks.pop()
            ordered.append(n)
            for m in list(graph[n]):
                graph[n].remove(m)
                if not graph[m]:
                    sinks.add(m)
        return ordered

    graph = build_graph(orderings)
    sinks = find_sinks(graph)
    return topological_sort(graph, sinks)

# Example usage
if __name__ == "__main__":
    result = _legacy_mergeOrderings([
        ['x', 'y', 'z'],
        ['q', 'z'],
        [1, 3, 5],
        ['z']
    ])
    print(result)  # Output: ['x', 'y', 'q', 1, 3, 5, 'z']

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    from itertools import chain, islice

    def is_subclass_of_any(cls, cls_list):
        return any(issubclass(cls, c) for c in cls_list if cls is not c)

    MinimalBases = []

    for cls in classes:
        if not is_subclass_of_any(cls, MinimalBases):
            MinimalBases.append(cls)
        else:
            MinimalBases = [c for c in MinimalBases if not is_subclass_of_any(c, [cls]) or c is cls]

    return MinimalBases

