from typing import Any, List, Tuple, Union

def _normalizeargs(sequence: Union[Tuple, List], output: List = None) -> List:
    if output is None:
        output = []

    for item in sequence:
        if isinstance(item, (tuple, list)):
            _normalizeargs(item, output)
        else:
            output.append(item)

    return output

