def difference(d1, d2, level=-1):
    if level == 0:
        return {}

    diff = {}
    for key in d1:
        if key not in d2:
            diff[key] = d1[key]
        elif isinstance(d1[key], dict) and isinstance(d2[key], dict):
            sub_diff = difference(d1[key], d2[key], level - 1)
            if sub_diff:
                diff[key] = sub_diff
        elif d1[key] != d2[key]:
            diff[key] = d1[key]

    return diff

import re
from typing import Dict, List, Union

class ValidationError(Exception):
    def __init__(self, messages: List[Dict[Union[str, int], str]]):
        self.messages = messages
        super().__init__(f"Label validation errors: {messages}")

def _validate_labels(labels: Dict[Union[str, int], str]):
    key_regex = re.compile(r'^[a-zA-Z0-9._-]+$')
    value_regex = re.compile(r'^[a-zA-Z0-9._-]+$')
    errors = []

    for key, value in labels.items():
        if not isinstance(key, (str, int)):
            errors.append({str(key): 'expected string or bytes-like object'})
        elif isinstance(key, str) and not key_regex.match(key):
            errors.append({key: f"Label key '{key}' does not match the regex '^[a-zA-Z0-9._-]+$'"})

        if not isinstance(value, (str, int)):
            errors.append({str(key): 'expected string or bytes-like object'})
        elif isinstance(value, str) and not value_regex.match(value):
            errors.append({str(key): f"Label value '{value}' does not match the regex '^[a-zA-Z0-9._-]+$'"})

    if errors:
        raise ValidationError(errors)

