    labels = {
        "key1": "valid",
        "key2": ["invalid"],
        "$$": "invalid",
        True: True,
    }
    try:
        _validate_labels(labels)
    except ValidationError as err:
        print(err.messages)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    import copy

    observer_schema = {}
    identifying_fields = ['apiVersion', 'kind', 'metadata']

    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            observer_schema[key] = generate_default_observer_schema_dict(value)
        elif isinstance(value, list):
            observer_schema[key] = [generate_default_observer_schema_dict(item) if isinstance(item, dict) else None for item in value]
        else:
            if first_level and key in identifying_fields:
                observer_schema[key] = copy.deepcopy(value)
            else:
                observer_schema[key] = None

    return observer_schema

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    for schema_item, resp_item in zip(observer_schema, response):
        if isinstance(schema_item, dict) and isinstance(resp_item, dict):
            if len(last_applied_manifest) < observer_schema.index(schema_item):
                last_applied_manifest.append({})
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[observer_schema.index(schema_item)],
                schema_item,
                resp_item
            )
        elif isinstance(schema_item, list) and isinstance(resp_item, list):
            if len(last_applied_manifest) < observer_schema.index(schema_item):
                last_applied_manifest.append([])
            update_last_applied_manifest_list_from_resp(
                last_applied_manifest[observer_schema.index(schema_item)],
                schema_item,
                resp_item
            )
        else:
            if len(last_applied_manifest) <= observer_schema.index(schema_item):
                last_applied_manifest.append(resp_item)
            elif last_applied_manifest[observer_schema.index(schema_item)] is None:
                last_applied_manifest[observer_schema.index(schema_item)] = resp_item

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    for key, schema_value in observer_schema.items():
        if key not in last_applied_manifest:
            if isinstance(schema_value, dict) and key in response:
                last_applied_manifest[key] = {}
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[key],
                    schema_value,
                    response[key]
                )
            elif isinstance(schema_value, list) and key in response:
                last_applied_manifest[key] = []
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[key],
                    schema_value,
                    response[key]
                )
            elif key in response:
                last_applied_manifest[key] = response[key]

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    for key, value in observer_schema.items():
        if key not in last_applied_manifest:
            if key in response:
                last_applied_manifest[key] = response[key]
            elif 'default' in value:
                last_applied_manifest[key] = value['default']
            else:
                raise KeyError(f"The observed field '{key}' is not present in the Kubernetes response and no default value is provided.")
        if isinstance(value, dict) and isinstance(last_applied_manifest.get(key), dict) and isinstance(response.get(key), dict):
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[key], value, response.get(key, {}))

