from typing import AnyStr, Union, Dict, Sequence, Tuple, Any
import re

class SQLParams:
    IN_STYLE_NAMED = 'named'
    IN_STYLE_ORDINAL = 'ordinal'

    def __init__(self, in_style: str):
        self.in_style = in_style

def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    if self.in_style == SQLParams.IN_STYLE_NAMED:
        out_style_params = {}
        placeholders = list(params.keys())
        for i, placeholder in enumerate(placeholders):
            out_style_params[f'param{i+1}'] = params[placeholder]
            sql = sql.replace(f':{placeholder}', f'${i+1}')
    elif self.in_style == SQLParams.IN_STYLE_ORDINAL:
        out_style_params = list(params)
        sql = re.sub(r'%s', lambda match: f'${out_style_params.index(params[match.start()-1])+1}', sql)
    else:
        raise ValueError("Unsupported in-style parameter type")

    return sql, out_style_params

# Example usage
if __name__ == "__main__":
    sql_params = SQLParams(SQLParams.IN_STYLE_NAMED)
    sql, params = sql_params.format("SELECT * FROM users WHERE name = :name AND age > :age", {"name": "Alice", "age": 30})
    print(sql, params)

    sql_params = SQLParams(SQLParams.IN_STYLE_ORDINAL)
    sql, params = sql_params.format("SELECT * FROM users WHERE name = %s AND age > %s", ["Alice", 30])
    print(sql, params)

from typing import AnyStr, Union, Iterable, Dict, Sequence, List, Tuple
import re

class SQLParams:
    in_style = 'named'  # or 'ordinal'

def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    def convert_params(sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
        if SQLParams.in_style == 'named':
            out_style_params = {f":{key}": value for key, value in params.items()}
            for key in out_style_params:
                sql = re.sub(rf"\:{key.split(':')[1]}\b", key, sql)
            return sql, list(out_style_params.values())
        elif SQLParams.in_style == 'ordinal':
            out_style_params = [value for value in params]
            sql = re.sub(rf"\%s", "?", sql)
            return sql, out_style_params

    formatted_sql = sql
    formatted_params = []

    for params in many_params:
        formatted_sql, out_style_params = convert_params(sql, params)
        formatted_params.append(out_style_params)

    return formatted_sql, formatted_params

