class OCFLValidator:
    def validate(self, path):
        """Validate OCFL object at path or pyfs root.

        Returns True if valid (warnings permitted), False otherwise.
        """
        if not os.path.exists(path):
            return False

        if not os.path.isdir(path):
            return False

        root_inventory_path = os.path.join(path, 'inventory.json')
        if not os.path.isfile(root_inventory_path):
            return False

        try:
            with open(root_inventory_path, 'r', encoding='utf-8') as f:
                inventory = json.load(f)
        except json.JSONDecodeError:
            return False

        if 'id' not in inventory or not isinstance(inventory['id'], str):
            return False

        if 'type' not in inventory or inventory['type'] != 'https://ocfl.io/1.0/spec/#inventory-type':
            return False

        if 'digestAlgorithm' not in inventory or inventory['digestAlgorithm'] not in ['sha256', 'sha512']:
            return False

        if 'head' not in inventory or not isinstance(inventory['head'], str):
            return False

        if 'manifest' not in inventory or not isinstance(inventory['manifest'], dict):
            return False

        for digest, filenames in inventory['manifest'].items():
            if not isinstance(filenames, list):
                return False
            for filename in filenames:
                if not os.path.isfile(os.path.join(path, filename)):
                    return False

        if 'versions' not in inventory or not isinstance(inventory['versions'], dict):
            return False

        for version, version_details in inventory['versions'].items():
            if not os.path.isdir(os.path.join(path, version)):
                return False
            if 'state' not in version_details or not isinstance(version_details['state'], dict):
                return False
            for digest, filenames in version_details['state'].items():
                if not isinstance(filenames, list):
                    return False
                for filename in filenames:
                    if not os.path.isfile(os.path.join(path, version, filename)):
                        return False

        return True

