import hashlib

class InventoryValidator:
    def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        if not isinstance(fixity, dict):
            raise ValueError("Fixity block must be a dictionary.")

        if not isinstance(manifest_files, list):
            raise ValueError("Manifest files must be a list.")

        manifest_files_set = set(manifest_files)

        for file_path, file_info in fixity.items():
            if file_path not in manifest_files_set:
                raise ValueError(f"File {file_path} in fixity block is not listed in the manifest.")

            if not isinstance(file_info, dict):
                raise ValueError(f"File info for {file_path} must be a dictionary.")

            if 'algorithm' not in file_info or 'value' not in file_info:
                raise ValueError(f"File info for {file_path} must contain 'algorithm' and 'value'.")

            algorithm = file_info['algorithm']
            if algorithm not in hashlib.algorithms_available:
                raise ValueError(f"Algorithm {algorithm} for file {file_path} is not available.")

import os

def _group_files_by_xml_filename(source, xmls, files):
    from collections import defaultdict

    grouped_files = defaultdict(list)
    xml_basenames = {os.path.basename(xml) for xml in xmls}

    for file in files:
        file_basename = os.path.basename(file)
        for xml_basename in xml_basenames:
            if file_basename.startswith(xml_basename.split('.')[0]):
                grouped_files[xml_basename].append(file)

    return dict(grouped_files)

