import re

def _extract_number_and_supplment_from_issue_element(issue):
    pattern = re.compile(r'(?P<number>\d+)?\s*(?P<suppl>suppl?\.?|spe|s)?\s*(?P<suffix>\d+|\d+-\d+|\w+)?', re.IGNORECASE)
    match = pattern.match(issue.strip())
    if match:
        number = match.group('number')
        suppl = match.group('suppl')
        suffix = match.group('suffix')
        if suppl:
            suppl = suppl.lower()
            if suffix:
                return number, f"{suppl} {suffix}".strip()
            return number, suppl
    return None, None

