class PrettyPrintable:
    def __init__(self, data):
        self.data = data

    def pretty(self, indent=0, debug=False):
        """
        Return a pretty formatted representation of self.
        """
        indent_str = ' ' * indent
        if isinstance(self.data, dict):
            result = f"{indent_str}{{\n"
            for key, value in self.data.items():
                if isinstance(value, PrettyPrintable):
                    result += f"{indent_str}  {key}: {value.pretty(indent + 2, debug)},\n"
                else:
                    result += f"{indent_str}  {key}: {repr(value)},\n"
            result += f"{indent_str}}}"
            return result
        elif isinstance(self.data, list):
            result = f"{indent_str}[\n"
            for item in self.data:
                if isinstance(item, PrettyPrintable):
                    result += f"{item.pretty(indent + 2, debug)},\n"
                else:
                    result += f"{indent_str}  {repr(item)},\n"
            result += f"{indent_str}]"
            return result
        else:
            return f"{indent_str}{repr(self.data)}"

