from functools import wraps

class HookType:
    def __init__(self, name):
        self.name = name

class HookRegistry:
    def __init__(self):
        self.handlers = {}

    def on(self, hook):
        def decorator(func):
            if hook not in self.handlers:
                self.handlers[hook] = []
            self.handlers[hook].append(func)
            @wraps(func)
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper
        return decorator

    def trigger(self, hook, *args, **kwargs):
        if hook in self.handlers:
            for handler in self.handlers[hook]:
                handler(*args, **kwargs)

# Example usage
registry = HookRegistry()

hook_example = HookType('example')

@registry.on(hook_example)
def example_handler():
    print("Example handler called")

registry.trigger(hook_example)

