from ruamel.yaml import ScalarNode, MappingNode

def deep_merge_nodes(nodes):
    from collections import defaultdict

    def merge_into(target, source):
        for key, value in source:
            if isinstance(value, MappingNode):
                if key not in target:
                    target.append((key, MappingNode(tag='tag:yaml.org,2002:map', value=[])))
                idx = next(i for i, (k, _) in enumerate(target) if k == key)
                merge_into(target[idx][1].value, value.value)
            else:
                if key in (k for k, _ in target):
                    idx = next(i for i, (k, _) in enumerate(target) if k == key)
                    target[idx] = (key, value)
                else:
                    target.append((key, value))

    merged = defaultdict(list)
    for key, value in nodes:
        merge_into(merged[key], [(key, value)])

    return [(key, value[0][1]) for key, value in merged.items()]

import argparse

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_results = {}
    remaining_arguments = unparsed_arguments

    for subparser_name, subparser in subparsers.items():
        try:
            parsed_args, remaining = subparser.parse_known_args(remaining_arguments)
            parsed_results[subparser_name] = parsed_args
            remaining_arguments = remaining
        except argparse.ArgumentError:
            continue

