from ruamel.yaml.nodes import ScalarNode, MappingNode

def deep_merge_nodes(nodes):
    merged = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged:
            if isinstance(merged[key], MappingNode) and isinstance(value_node, MappingNode):
                merged_value = merged[key].value.copy()
                for sub_key_node, sub_value_node in value_node.value:
                    merged_value.append((sub_key_node, sub_value_node))
                merged[key] = MappingNode(tag='tag:yaml.org,2002:map', value=merged_value)
            else:
                merged[key] = value_node
        else:
            merged[key] = value_node
    return [(key_node, value_node) for key_node, value_node in merged.items()]

