def subprocess_run_helper(func, *args, timeout, extra_env=None):
    def run_function():
        func(*args)

    if getattr(sys, 'frozen', False):
        script_path = sys.executable
    else:
        script_path = os.path.abspath(__file__)

    with open('temp_func.pkl', 'wb') as f:
        pickle.dump(run_function, f)

    env = os.environ.copy()
    if extra_env:
        env.update(extra_env)

    try:
        result = subprocess.run(
            [sys.executable, script_path, 'temp_func.pkl'],
            shell=False,
            env=env,
            timeout=timeout
        )
    finally:
        os.remove('temp_func.pkl')

    return result

