def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()

    for subj, pred, obj in graph:
        if pred == prop:
            # If the subject is not an object of any other triple with the same property, it's a root
            if subj not in [o for s, p, o in graph if p == prop]:
                roots.add(subj)

    return roots

