from datetime import datetime, timedelta, timezone, tzinfo

class Time:
    NANOSECONDS_IN_A_DAY = 86400000000000

    @classmethod
    def from_ticks(cls, ticks, tz=None):
        if not (0 <= ticks < cls.NANOSECONDS_IN_A_DAY):
            raise ValueError("ticks is out of bounds (0 <= ticks < 86400000000000)")

        seconds = ticks // 1_000_000_000
        nanoseconds = ticks % 1_000_000_000
        naive_time = datetime.utcfromtimestamp(0) + timedelta(seconds=seconds, microseconds=nanoseconds // 1000)

        if tz is not None:
            return naive_time.replace(tzinfo=timezone.utc).astimezone(tz)

        return naive_time.time()

