class LenaValueError(Exception):
    pass

class Histogram:
    def __init__(self):
        self.bins = []
        self._scale = None

    def fill(self, value):
        # Example method to fill the histogram
        self.bins.append(value)
        # Invalidate the scale when histogram is filled
        self._scale = None

    def scale(self, other=None, recompute=False):
        if other is None:
            if self._scale is None or recompute:
                self._scale = sum(self.bins)
            return self._scale
        else:
            if self._scale is None:
                self._scale = self.scale()
            if self._scale == 0:
                raise LenaValueError("Histogram with scale equal to zero can't be rescaled.")
            scale_factor = other / self._scale
            self._scale = other
            for i in range(len(self.bins)):
                self.bins[i] *= scale_factor
            return self._scale

