class Graph:
    def __init__(self, data, field_names, scale=None):
        self.data = data
        self.field_names = field_names
        self.scale = scale

class Histogram:
    def __init__(self, bins, bin_edges, scale=None):
        self.bins = bins
        self.bin_edges = bin_edges
        self.scale = scale

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_: bin_

    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

    if len(field_names) != 1 + (1 if isinstance(make_value(bin_), (tuple, list)) else 0):
        raise ValueError("field_names must have correct number of fields")

    x_values = []
    y_values = []

    for i, bin_content in enumerate(hist.bins):
        if get_coordinate == "left":
            x = hist.bin_edges[i]
        elif get_coordinate == "right":
            x = hist.bin_edges[i + 1]
        elif get_coordinate == "middle":
            x = (hist.bin_edges[i] + hist.bin_edges[i + 1]) / 2

        y = make_value(bin_content)

        x_values.append(x)
        if isinstance(y, (tuple, list)):
            y_values.extend(y)
        else:
            y_values.append(y)

    data = np.array([x_values] + [y_values[i::len(y_values)//len(x_values)] for i in range(0, len(y_values), len(y_values)//len(x_values))]).T

    if scale is True:
        scale = hist.scale

    return Graph(data, field_names, scale)

