from zope.interface import Interface, providedBy, implementer
from zope.interface.exceptions import Invalid
from zope.interface.verify import verifyObject, verifyClass

def _verify(iface, candidate, tentative=False, vtype=None):
    errors = []

    if not tentative and not iface.providedBy(candidate):
        errors.append(f"Candidate does not provide the interface: {iface}")

    if vtype is None:
        vtype = type(candidate) if isinstance(candidate, object) else candidate

    try:
        verifyObject(iface, candidate)
    except Invalid as e:
        errors.extend(e.args)

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid(", ".join(errors))

    return True
