from zope.interface import Interface, Attribute, implementer, providedBy, Invalid
from inspect import signature, Parameter
from typing import List

class VerificationError(Exception):
    def __init__(self, errors: List[str]):
        self.errors = errors
        super().__init__(f"Multiple verification errors: {', '.join(errors)}")

def verifyObject(iface: Interface, candidate, tentative: bool = False) -> bool:
    errors = []

    if not tentative:
        if not providedBy(candidate).extends(iface):
            errors.append(f"Candidate does not provide the interface {iface.__name__}")

    for name, method in iface.namesAndDescriptions():
        if isinstance(method, MethodDescription):
            if not hasattr(candidate, name):
                errors.append(f"Candidate does not define method '{name}'")
            else:
                cand_method = getattr(candidate, name)
                if not callable(cand_method):
                    errors.append(f"Candidate attribute '{name}' is not callable")
                else:
                    try:
                        sig = signature(cand_method)
                        expected_sig = method.getSignatureInfo()
                        if sig != expected_sig:
                            errors.append(f"Method '{name}' has incorrect signature. Expected {expected_sig}, got {sig}")
                    except Exception as e:
                        errors.append(f"Error checking method '{name}': {e}")
        elif isinstance(method, Attribute):
            if not hasattr(candidate, name):
                errors.append(f"Candidate does not define attribute '{name}'")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise VerificationError(errors)

    return True

class MethodDescription:
    def __init__(self, signature_info):
        self.signature_info = signature_info

    def getSignatureInfo(self):
        return self.signature_info

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if isinstance(iface, type) and isinstance(candidate, type):
        return issubclass(candidate, iface)
    return False

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    metas = set(type(base) for base in bases)
    if len(metas) == 1:
        return metas.pop()
    elif not metas:
        return type
    else:
        raise TypeError("metaclass conflict: the metaclass of a derived class must be a (non-strict) subclass of the metaclasses of all its bases")

class DictWithPop:
    def __init__(self):
        self._dict = {}

    def pop(self, key, default=None):
        """
        D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
        If key is not found, d is returned if given, otherwise KeyError is raised.
        """
        if key in self._dict:
            return self._dict.pop(key)
        elif default is not None:
            return default
        else:
            raise KeyError(key)

