    d._dict = {'a': 1, 'b': 2}
    print(d.pop('a'))        # Output: 1
    print(d.pop('c', 'not found'))  # Output: not found
    try:
        print(d.pop('d'))    # Raises KeyError
    except KeyError as e:
        print(e)             # Output: d

from collections import OrderedDict, Counter

class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = OrderedDict()
        self.freq = Counter()
        self.min_freq = 0

    def get(self, key: int) -> int:
        if key not in self.cache:
            return -1
        value = self.cache.pop(key)
        self.freq[key] += 1
        new_freq = self.freq[key]
        self.cache[key] = value
        if new_freq == self.min_freq and not any(f == self.min_freq for f in self.freq.values()):
            self.min_freq += 1
        return value

    def put(self, key: int, value: int) -> None:
        if self.capacity == 0:
            return
        if key in self.cache:
            self.cache.pop(key)
        elif len(self.cache) >= self.capacity:
            while self.min_freq:
                for k, v in self.cache.items():
                    if self.freq[k] == self.min_freq:
                        self.cache.pop(k)
                        self.freq.pop(k)
                        break
                else:
                    self.min_freq += 1
                break
        self.cache[key] = value
        self.freq[key] = 1
        self.min_freq = 1

    def popitem(self):
        """Remove and return the `(key, value)` pair least frequently used."""
        if not self.cache:
            raise KeyError("popitem(): cache is empty")
        key_to_pop = next(k for k, v in self.cache.items() if self.freq[k] == self.min_freq)
        value = self.cache.pop(key_to_pop)
        self.freq.pop(key_to_pop)
        if not any(f == self.min_freq for f in self.freq.values()):
            self.min_freq += 1
        return key_to_pop, value

from collections import OrderedDict

class LRUCache:
    def __init__(self):
        self.cache = OrderedDict()

    def popitem(self):
        """Remove and return the `(key, value)` pair least recently used."""
        if not self.cache:
            raise KeyError("popitem(): dictionary is empty")
        return self.cache.popitem(last=False)

