from typing import NamedTuple, Optional

class RequestType(NamedTuple):
    public_message: Optional[str]
    private_message: Optional[str]
    legacy_payload: Optional[bool]

def identify_request(request: RequestType) -> str:
    if request.public_message:
        return "Diaspora Public Message"
    elif request.private_message:
        return "Diaspora Private Message"
    elif request.legacy_payload:
        return "Diaspora Legacy Payload"
    else:
        return "Unknown Diaspora Request"

