import requests
from xml.etree import ElementTree

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    base_url = "https://diaspora-federation.tokyo/.well-known/webfinger"
    params = {
        "resource": f"acct:{handle}"
    }

    response = requests.get(base_url, params=params)
    if response.status_code != 200:
        raise Exception(f"Failed to retrieve webfinger document for {handle}: {response.status_code}")

    try:
        root = ElementTree.fromstring(response.content)
        links = {}
        for link in root.findall("{http://salmon-protocol.org/ns/magic#}link"):
            rel = link.get("rel")
            href = link.get("href")
            links[rel] = href
        return links
    except ElementTree.ParseError as e:
        raise Exception(f"Failed to parse webfinger document for {handle}: {e}")

def dict_insert(dic, val, key, *keys):
    current_level = dic
    for k in keys[:-1]:
        if k not in current_level:
            current_level[k] = {}
        current_level = current_level[k]
    if keys:
        current_level[keys[-1]] = val
    else:
        current_level[key] = val

