class SpecFileParser:
    def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files. """
        if 'include' in parser_dict:
            include_path = parser_dict['include']
            if os.path.exists(include_path):
                with open(include_path, 'r') as file:
                    included_data = json.load(file)
                    parser_dict.update(included_data)
            else:
                raise FileNotFoundError(f"The included file {include_path} does not exist.")
        return parser_dict

