import argparse

class CommandParser:
    def __init__(self):
        self.parsers = {}
        self._create_parsers()

    def _create_parsers(self):
        parser_main = argparse.ArgumentParser(add_help=False)
        parser_main.add_argument('--main-option', help='Main option description')
        self.parsers['main'] = parser_main

        parser_virsh = argparse.ArgumentParser(add_help=False)
        parser_virsh.add_argument('--virsh-option', help='Virsh option description')
        self.parsers['virsh'] = parser_virsh

        parser_ospd = argparse.ArgumentParser(add_help=False)
        parser_ospd.add_argument('--ospd-option', help='OSPD option description')
        self.parsers['ospd'] = parser_ospd

    def get_parser_option_specs(self, command_name):
        """Gets all the options for the specified command

        :param command_name: the command name (main, virsh, ospd, etc...)
        :return: the list of all command options
        """
        if command_name in self.parsers:
            return self.parsers[command_name]._actions[1:]  # Skip the help action
        else:
            return []

