    print(validator.validate_min_max_args([2, 5, 8]))  # Output: True
    print(validator.validate_min_max_args([0, 11, 5])) # Output: False

import argparse

class ArgumentSplitter:
    def get_nested_custom_and_control_args(self, args):
        control_args = {}
        nested_args = {}
        custom_args = {}

        for arg, value in args.items():
            if arg.startswith('control_'):
                control_args[arg] = value
            elif arg.startswith('custom_'):
                custom_args[arg] = value
            else:
                nested_args[arg] = value

        # Assuming nested and custom args should be merged into nested_args
        nested_args.update(custom_args)

        return control_args, nested_args

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Split arguments into control, nested, and custom.")
    parser.add_argument('--control_arg1', help='Control argument 1')
    parser.add_argument('--control_arg2', help='Control argument 2')
    parser.add_argument('--custom_arg1', help='Custom argument 1')
    parser.add_argument('--nested_arg1', help='Nested argument 1')

    args = vars(parser.parse_args())

    splitter = ArgumentSplitter()
    control_args, nested_args = splitter.get_nested_custom_and_control_args(args)

    print("Control Args:", control_args)
    print("Nested Args:", nested_args)

class Merger:
    @staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if extra_vars is None:
            extra_vars = {}
        if isinstance(extra_vars, list):
            extra_vars_dict = {}
            for item in extra_vars:
                if isinstance(item, dict):
                    extra_vars_dict.update(item)
                elif isinstance(item, str):
                    key, value = item.split('=', 1)
                    extra_vars_dict[key] = value
            extra_vars = extra_vars_dict
        vars_dict.update(extra_vars)
        return vars_dict

# Example usage
if __name__ == "__main__":
    vars_dict = {'a': 1, 'b': 2}
    extra_vars = ['c=3', {'d': 4, 'e': 5}]
    merged_vars = Merger.merge_extra_vars(vars_dict, extra_vars)
    print(merged_vars)

import os
import json
from itertools import chain

def flatten_dict(d, parent_key='', sep='_'):
    items = []
    for k, v in d.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.extend(flatten_dict(v, new_key, sep=sep).items())
        else:
            items.append((new_key, v))
    return dict(items)

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    spec_path = os.path.join(plugin_dir, 'plugin_spec.json')
    if not os.path.exists(spec_path):
        raise FileNotFoundError(f"Plugin spec file not found at {spec_path}")

    with open(spec_path, 'r') as file:
        plugin_spec = json.load(file)

    return flatten_dict(plugin_spec)

import os

class ConfigInjector:
    def inject_config(self):
        """Set the environment variable for config path, if it is undefined."""
        if os.getenv('CONFIG_PATH') is None:
            os.environ['CONFIG_PATH'] = '/path/to/default/config'

import os

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path.startswith(root):
        raise ValueError(f"Path '{path}' does not start with root '{root}'")
    return os.path.relpath(path, root)

# Example usage
if __name__ == "__main__":
    try:
        print(strip_root("/root/directory/file.txt", "/root"))
    except ValueError as e:
        print(e)
